//! Esperanto hyphenation by morpheme: a word is split into prefixes, roots, suffixes and its
//! grammatical ending, and breaks go only between morphemes (`tranĉ-ilo`, never `tran-ĉi-lo`;
//! `mal-san-ul-ejo`). The ending stays with the morpheme before it, and so does a linking vowel
//! inside a compound (`akvo-birdo`). A word that doesn't split into known pieces isn't broken.
//!
//! The roots (`assets/hyphenation/eo.roots`, one per line) come from English Wiktionary's
//! Esperanto entries, CC BY-SA 4.0, extracted by kaikki.org (attribution in `ASSETS.md`); the file
//! is generated by `examples/eohyphgen.rs`, never edited by hand. They are kept as a sorted slice of
//! the embedded text and looked up by binary search. The affixes are the official ones (Fundamento
//! and Oficialaj Aldonoj). Words over 64 chars, ending included, aren't segmented.

use std::sync::OnceLock;

static EO_ROOTS: &str = include_str!("../../../../assets/hyphenation/eo.roots");

/// Prefixes: only at the start of a word or after another prefix.
pub const PREFIXES: &[&str] = &["bo", "dis", "ek", "eks", "ge", "mal", "re", "pra", "fi", "fuŝ", "mis"];

/// Suffixes, participle suffixes included: only after another morpheme.
pub const SUFFIXES: &[&str] = &[
    "aĉ", "ad", "aĵ", "an", "ar", "ebl", "ec", "eg", "ej", "em", "end", "er", "estr", "et", "id", "ig", "iĝ", "il", "in", "ind", "ing", "ism", "ist",
    "obl", "on", "op", "uj", "ul", "um", "ĉj", "nj", "ant", "int", "ont", "at", "it", "ot",
];

/// Longest word (in chars) segmented, its ending included: the search is quadratic in the length.
pub const MAX_WORD: usize = 64;

/// Longest morpheme tried (in chars).
const MAX_PIECE: usize = 24;

/// Longest affix (in chars): longer pieces are only looked up as roots.
const MAX_AFFIX: usize = 4;

/// The bundled roots, sorted and without duplicates: slices of the embedded text, built on first
/// use without copying a root.
pub fn roots() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| parse_roots(EO_ROOTS))
}

/// Whether `piece` is a bundled root (a binary search).
pub fn is_root(piece: &str) -> bool {
    roots().binary_search(&piece).is_ok()
}

/// A root list: one root per line, surrounding spaces trimmed, `#` comments and blank lines
/// skipped; sorted, duplicates dropped.
pub fn parse_roots(text: &str) -> Vec<&str> {
    let mut roots: Vec<&str> = text.lines().map(str::trim).filter(|l| !l.is_empty() && !l.starts_with('#')).collect();
    roots.sort_unstable();
    roots.dedup();
    roots
}

/// Length in chars of the grammatical ending of a lowercase word (`-o`, `-a`, `-e`, `-i`, `-as`,
/// `-is`, `-os`, `-us`, `-u`, then `-j`, then `-n`), 0 if none; at least two chars stay before it.
pub fn ending_len(word: &[char]) -> usize {
    const ENDINGS: &[&str] = &["ojn", "ajn", "oj", "aj", "on", "an", "en", "as", "is", "os", "us", "o", "a", "e", "i", "u"];
    for e in ENDINGS {
        let len = e.chars().count();
        if word.len() >= len + 2 && word.iter().rev().take(len).rev().copied().eq(e.chars()) {
            return len;
        }
    }
    0
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Prefix,
    Root,
    Suffix,
}

/// What a morpheme costs: roots more than affixes, short roots more still (they match by chance).
fn cost(len: usize, kind: Kind) -> f32 {
    match kind {
        Kind::Root => {
            1.0 + match len {
                0 | 1 => 9.0,
                2 => 1.2,
                3 => 0.3,
                _ => 0.0,
            }
        }
        Kind::Prefix => 0.6,
        Kind::Suffix => 0.55,
    }
}

/// Extra cost of a linking vowel after a root inside a compound (`akv-o-birdo`).
const LINK: f32 = 0.35;

/// The cheapest split of a lowercase stem (a word without its ending) into morphemes, with its
/// cost: the char index where each morpheme after the first starts. None when no split covers the
/// stem with at least one root (affixes alone would split names and foreign words). `is_root` says
/// whether a piece is a root.
///
/// Allocation-free apart from the stem's text and the result: the table is on the stack and the
/// pieces looked up are slices of the stem.
pub fn segment(stem: &[char], is_root: &dyn Fn(&str) -> bool) -> Option<(Vec<usize>, f32)> {
    let n = stem.len();
    if n == 0 || n > MAX_WORD {
        return None;
    }
    let text: String = stem.iter().collect();
    // Byte offset of each char in `text`, and of its end.
    let mut at = [0usize; MAX_WORD + 1];
    let mut byte = 0;
    for (slot, c) in at.iter_mut().zip(stem) {
        *slot = byte;
        byte += c.len_utf8();
    }
    *at.get_mut(n)? = byte;
    // A stem that is a root stays whole: one root costs at most 1.3 for 3 chars or more (2.2 for 2),
    // and any split with a root costs at least 1.55 (a root and an affix), so no split beats it.
    if is_root(&text) {
        return Some((Vec::new(), cost(n, Kind::Root)));
    }
    // best[i][r]: the cheapest split of stem[..i], with a root among its morphemes when r is 1,
    // without when 0. Splits with and without a root are kept apart so that a cheaper rootless one
    // never hides the split with a root.
    let mut best = [[None::<Step>; 2]; MAX_WORD + 1];
    best.get_mut(0)?[0] = Some(Step { cost: 0.0, start: 0, kind: Kind::Prefix, had_root: false });
    for i in 0..n {
        let Some(&from_byte) = at.get(i) else { break };
        for had_root in [false, true] {
            let Some(Some(from)) = best.get(i).map(|b| b[usize::from(had_root)]) else { continue };
            for j in i + 1..=n.min(i + MAX_PIECE) {
                let Some(piece) = at.get(j).and_then(|&to| text.get(from_byte..to)) else { break };
                let affix = j - i <= MAX_AFFIX;
                if is_root(piece) {
                    let step = Step { cost: from.cost + cost(j - i, Kind::Root), start: i, kind: Kind::Root, had_root };
                    relax(&mut best, j, true, step);
                    if j < n && matches!(stem.get(j), Some('o' | 'a' | 'e' | 'i')) {
                        relax(&mut best, j + 1, true, Step { cost: step.cost + LINK, ..step });
                    }
                }
                if affix && had_root && SUFFIXES.contains(&piece) {
                    relax(&mut best, j, true, Step { cost: from.cost + cost(j - i, Kind::Suffix), start: i, kind: Kind::Suffix, had_root });
                }
                if affix && (i == 0 || from.kind == Kind::Prefix) && PREFIXES.contains(&piece) {
                    relax(&mut best, j, had_root, Step { cost: from.cost + cost(j - i, Kind::Prefix), start: i, kind: Kind::Prefix, had_root });
                }
            }
        }
    }
    let total = best.get(n)?[1]?.cost;
    let mut starts = Vec::new();
    let (mut at, mut has_root) = (n, true);
    while at > 0 {
        let step = best.get(at)?[usize::from(has_root)]?;
        if step.start > 0 {
            starts.push(step.start);
        }
        (at, has_root) = (step.start, step.had_root);
    }
    starts.reverse();
    Some((starts, total))
}

/// The last morpheme of a split: its cost so far, where it starts, its kind, and whether the
/// split before it already had a root.
#[derive(Clone, Copy)]
struct Step {
    cost: f32,
    start: usize,
    kind: Kind,
    had_root: bool,
}

fn relax(best: &mut [[Option<Step>; 2]], at: usize, has_root: bool, cand: Step) {
    if let Some(slot) = best.get_mut(at).map(|b| &mut b[usize::from(has_root)])
        && slot.is_none_or(|s| cand.cost < s.cost)
    {
        *slot = Some(cand);
    }
}

/// Break points (char indices) of a lowercase Esperanto word: between its morphemes, never
/// before the ending alone. Sorted, without duplicates, strictly inside the word. Callers that see
/// the same word often cache the result (the composer does, per word and limits).
pub fn breaks(word: &[char]) -> Vec<usize> {
    breaks_with(word, &is_root)
}

/// [`breaks`] with another root set.
pub fn breaks_with(word: &[char], is_root: &dyn Fn(&str) -> bool) -> Vec<usize> {
    if word.len() > MAX_WORD {
        return Vec::new();
    }
    let end = ending_len(word);
    let stem = word.get(..word.len() - end).unwrap_or(word);
    segment(stem, is_root).map(|(s, _)| s).unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn chars(w: &str) -> Vec<char> {
        w.chars().collect()
    }

    /// `word` with a hyphen at each break point, from `pts`.
    fn show(word: &str, pts: &[usize]) -> String {
        let mut s = String::new();
        for (i, c) in word.chars().enumerate() {
            if pts.contains(&i) {
                s.push('-');
            }
            s.push(c);
        }
        s
    }

    fn h(word: &str) -> String {
        show(word, &breaks(&chars(word)))
    }

    /// Hyphenated with a small root set, independent of the bundled list.
    fn hw(word: &str) -> String {
        const ROOTS: &[&str] = &["akv", "bird", "san", "lern", "direktor", "kat", "ab", "fer", "voj"];
        show(word, &breaks_with(&chars(word), &|p| ROOTS.contains(&p)))
    }

    const ALPHABET: &str = "abcdefghijklmnoprstuvzĉĝĥĵŝŭ";

    #[test]
    fn bundled_roots_are_sorted_unique_and_lowercase_esperanto() {
        let r = roots();
        assert_eq!(r.len(), 7331, "eo.roots changed: update this count with the file");
        assert!(r.windows(2).all(|w| w[0] < w[1]), "sorted, no duplicates");
        for root in r {
            assert!(root.chars().all(|c| ALPHABET.contains(c)), "{root}: Esperanto letters only");
        }
        assert!(is_root("tranĉ"));
        assert!(!is_root("tranĉi"));
        // The file itself is sorted too, so a regenerated list diffs cleanly.
        let lines: Vec<&str> = EO_ROOTS.lines().filter(|l| !l.starts_with('#')).collect();
        assert_eq!(lines, r, "eo.roots lines are the sorted root list");
    }

    #[test]
    fn root_lists_skip_comments_blanks_and_duplicates() {
        let text = "# header\n\nvoj\n  akv  \nbird\n# note\nvoj\n\n";
        assert_eq!(parse_roots(text), vec!["akv", "bird", "voj"]);
        assert!(parse_roots("").is_empty());
        assert!(parse_roots("# only a comment\n\n").is_empty());
    }

    #[test]
    fn affixes_fit_the_affix_length() {
        for a in PREFIXES.iter().chain(SUFFIXES) {
            assert!(a.chars().count() <= MAX_AFFIX, "{a} is longer than MAX_AFFIX");
        }
    }

    #[test]
    fn words_break_between_morphemes_not_syllables() {
        assert_eq!(h("tranĉilo"), "tranĉ-ilo");
        assert_eq!(h("tranĉilojn"), "tranĉ-ilojn");
        assert_eq!(h("malsanulejo"), "mal-san-ul-ejo");
        assert_eq!(h("malegaleco"), "mal-egal-eco");
        assert_eq!(h("lernejo"), "lern-ejo");
        assert_eq!(h("vaporŝipo"), "vapor-ŝipo");
        assert_eq!(h("fervojo"), "fer-vojo");
        assert_eq!(h("direktoro"), "direktoro", "one root, not direkt-or-");
    }

    /// Words that split two ways and where the segmenter picks the wrong one (Wiktionary's
    /// breaks in the comments). Recorded so that a change in either direction shows; fix them in
    /// the data (the Wiktionary etymology or `NOT_ROOTS`), then update the expected value here.
    #[test]
    fn known_wrong_splits() {
        assert_eq!(h("malvera"), "malv-era"); // mal-vera
        assert_eq!(h("masonisto"), "mas-on-isto"); // mason-isto
        assert_eq!(h("teleregilo"), "teler-eg-ilo"); // telereg-ilo
        assert_eq!(h("malkomplikeco"), "mal-komp-lik-eco"); // mal-komplik-eco
    }

    #[test]
    fn prefixes_chain_only_at_the_start() {
        assert_eq!(hw("remalsanigi"), "re-mal-san-igi", "two prefixes, a root, a suffix");
        assert_eq!(hw("sanmalo"), "sanmalo", "mal after a root isn't a prefix: no split covers the word");
    }

    #[test]
    fn suffixes_need_a_root_before_them() {
        assert_eq!(hw("saneco"), "san-eco");
        assert_eq!(hw("malsaneco"), "mal-san-eco");
        assert_eq!(hw("malego"), "malego", "mal + eg: affixes alone are not a word");
        assert_eq!(h("malego"), "malego");
    }

    #[test]
    fn a_linking_vowel_stays_with_its_root() {
        assert_eq!(h("akvobirdo"), "akvo-birdo");
        assert_eq!(hw("akvobirdo"), "akvo-birdo", "before another root");
        assert_eq!(hw("sanio"), "sanio", "at the end of the stem: no break before it");
        assert_eq!(hw("sanibirdo"), "sani-birdo");
        assert_eq!(hw("ferovojo"), "fero-vojo");
    }

    #[test]
    fn the_ending_is_never_split_off() {
        let r = |p: &str| p == "parol";
        assert_eq!(breaks_with(&chars("parolas"), &r), Vec::<usize>::new());
        assert_eq!(breaks_with(&chars("parolojn"), &r), Vec::<usize>::new());
    }

    #[test]
    fn endings() {
        let e = |w: &str| ending_len(&chars(w));
        assert_eq!(e("domo"), 1);
        assert_eq!(e("domoj"), 2);
        assert_eq!(e("domojn"), 3);
        assert_eq!(e("bela"), 1);
        assert_eq!(e("belajn"), 3);
        assert_eq!(e("parolas"), 2);
        assert_eq!(e("parolus"), 2);
        assert_eq!(e("hejmen"), 2);
        assert_eq!(e("tre"), 1, "two chars stay");
        // Fewer than two chars would stay before the ending: none.
        assert_eq!(e("ne"), 0);
        assert_eq!(e("la"), 0);
        assert_eq!(e("kaj"), 0);
        assert_eq!(e("ojn"), 0);
        assert_eq!(e("oj"), 0);
        assert_eq!(e("kun"), 0);
        assert_eq!(e("o"), 0);
        assert_eq!(e(""), 0);
    }

    #[test]
    fn unknown_words_stay_whole() {
        assert_eq!(h("xyzzyplugh"), "xyzzyplugh");
    }

    #[test]
    fn the_word_limit_counts_the_ending() {
        let is_root = |p: &str| p == "ab";
        let word = |pairs: usize, ending: &str| chars(&format!("{}{ending}", "ab".repeat(pairs)));
        // Exactly 64 chars (62-char stem): segmented.
        assert_eq!(word(31, "oj").len(), MAX_WORD);
        assert_eq!(breaks_with(&word(31, "oj"), &is_root).len(), 30);
        // 65 chars, whose 62-char stem tiles: over the limit.
        assert!(breaks_with(&word(31, "ojn"), &is_root).is_empty());
        // The stem limit for `segment` itself.
        assert!(segment(&word(32, ""), &is_root).is_some(), "64-char stem");
        assert!(segment(&chars(&format!("{}a", "ab".repeat(32))), &is_root).is_none(), "65-char stem");
    }

    #[test]
    fn hostile_words_are_bounded() {
        let long: Vec<char> = "malsanulejo".repeat(50).chars().collect();
        assert!(breaks(&long).is_empty());
        assert!(breaks(&[]).is_empty());
        assert!(breaks(&['o']).is_empty());
    }

    /// Breaks are sorted, unique and strictly inside the word, never before the ending alone.
    fn check_invariants(word: &[char], pts: &[usize]) {
        assert!(pts.windows(2).all(|w| w[0] < w[1]), "{pts:?} sorted and unique");
        assert!(pts.iter().all(|&p| p > 0 && p < word.len()), "{pts:?} inside {}", word.len());
        if let Some(&last) = pts.last() {
            assert!(last < word.len() - ending_len(word), "{pts:?}: no break before the ending alone");
        }
    }

    proptest! {
        #[test]
        fn any_text_breaks_safely(w in any::<String>()) {
            let c = chars(&w);
            check_invariants(&c, &breaks(&c));
        }

        #[test]
        fn esperanto_like_text_breaks_safely(w in "[abcdefghijklmnoprstuvzĉĝĥĵŝŭABCĈŜ' .-]{0,80}") {
            let c = chars(&w);
            check_invariants(&c, &breaks(&c));
            let lower: Vec<char> = w.to_lowercase().chars().collect();
            check_invariants(&lower, &breaks(&lower));
        }

        #[test]
        fn words_built_from_morphemes_break_at_their_seams(
            pre in proptest::sample::subsequence(vec!["mal", "re"], 0..=2),
            root in proptest::sample::select(vec!["san", "lern", "kat", "akv"]),
            suf in proptest::sample::subsequence(vec!["ul", "ej", "ar"], 0..=2),
            end in proptest::sample::select(vec!["o", "oj", "ojn", "a", "as", "i"]),
        ) {
            let word: String = pre.iter().copied().chain([root]).chain(suf.iter().copied()).chain([end]).collect();
            let c = chars(&word);
            let pts = breaks_with(&c, &|p| p == root);
            let mut want = Vec::new();
            let mut at = 0;
            for m in pre.iter().chain([&root]).chain(suf.iter()) {
                if at > 0 {
                    want.push(at);
                }
                at += m.chars().count();
            }
            prop_assert_eq!(pts, want, "{}", word);
        }
    }
}
